```javascript
/**
 * Creates a debounced async function with cancellation support
 * @param {Function} asyncFn - The async function to debounce
 * @param {number} delay - Delay in milliseconds
 * @returns {Function} Debounced function with cancel method
 */
function createDebouncedAsync(asyncFn, delay) {
  let timeoutId = null;
  let abortController = null;
  let pendingPromise = null;

  const debouncedFn = function(...args) {
    // Cancel any pending execution
    if (timeoutId) {
      clearTimeout(timeoutId);
    }

    // Abort any in-flight request
    if (abortController) {
      abortController.abort();
    }

    // Create new promise for this call
    return new Promise((resolve, reject) => {
      timeoutId = setTimeout(async () => {
        // Create new AbortController for this request
        abortController = new AbortController();
        const signal = abortController.signal;

        try {
          // Check if request was cancelled before starting
          if (signal.aborted) {
            reject(new DOMException('Aborted', 'AbortError'));
            return;
          }

          // Execute the async function with signal
          const result = await asyncFn(...args, signal);

          // Check if request was cancelled during execution
          if (signal.aborted) {
            reject(new DOMException('Aborted', 'AbortError'));
            return;
          }

          resolve(result);
        } catch (error) {
          // Don't reject if it was our own abort
          if (error.name === 'AbortError') {
            reject(error);
          } else {
            reject(error);
          }
        } finally {
          timeoutId = null;
          abortController = null;
          pendingPromise = null;
        }
      }, delay);
    });
  };

  // Add cancel method
  debouncedFn.cancel = function() {
    if (timeoutId) {
      clearTimeout(timeoutId);
      timeoutId = null;
    }
    if (abortController) {
      abortController.abort();
      abortController = null;
    }
    pendingPromise = null;
  };

  return debouncedFn;
}

