def permutations_generator(lst):
    """Generate permutations one at a time to save memory."""
    if len(lst) <= 1:
        yield lst[:]
        return

    for i in range(len(lst)):
        current = lst[i]
        remaining = lst[:i] + lst[i+1:]

        for perm in permutations_generator(remaining):
            yield [current] + perm

