### 6. Type Safety and Validation

```python
from typing import List, TypeVar, Union

T = TypeVar('T')

def find_permutations_typed(lst: List[T]) -> List[List[T]]:
    """Type-safe version with input validation."""
    if not isinstance(lst, list):
        raise TypeError("Input must be a list")

    if len(lst) <= 1:
        return [lst[:]]

    result = []

    for i in range(len(lst)):
        current = lst[i]
        remaining = lst[:i] + lst[i+1:]

        for perm in find_permutations_typed(remaining):
            result.append([current] + perm)

    return result
